#!/bin/sh
# Build stock.txt from the day's movements log.  Include every SKU observed in
# the log, even when its net movement is zero, plus catalog-only SKUs.
awk '
    { net[$1] += ($2 == "receipt" ? $3 : -$3); sku[$1] = 1 }
    END {
        # Catalog SKU with no movement records must still be reported.
        sku["SKU-9"] = 1
        for (item in sku) print item, net[item] + 0
    }
' movements.log | sort > stock.txt
